@@ -31,6 +31,7 @@ public final class ReservationService {
         if (request.guests() < 1) {
             throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
         }
+        validateRatePlan(request);
         Room room = rooms.find(request.roomNumber())
                 .orElseThrow(() -> new HotelException(
                         ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
@@ -43,10 +44,47 @@ public final class ReservationService {
             throw new HotelException(
                     ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
         }
-        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
+        Price price =
+                priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
         return store.add(request, price);
     }

+    private void validateRatePlan(NewReservation request) {
+        switch (request.ratePlan()) {
+            case CORPORATE:
+                if (!isValidCompanyCode(request.companyCode())) {
+                    throw new HotelException(ErrorCode.INVALID_REQUEST, "invalid company code");
+                }
+                break;
+            case WEEKEND_PACKAGE:
+                if (!isWeekendStay(request.checkIn(), request.checkOut())) {
+                    throw new HotelException(ErrorCode.INVALID_REQUEST, "weekend package must be Friday to Sunday");
+                }
+                break;
+            case LONG_STAY:
+                long nights = java.time.temporal.ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
+                if (nights < 7) {
+                    throw new HotelException(ErrorCode.INVALID_REQUEST, "long stay requires at least 7 nights");
+                }
+                break;
+            default:
+                break;
+        }
+    }
+
+    private boolean isValidCompanyCode(String code) {
+        return code != null && (code.equals("TECNOSUL") || code.equals("AGROVALE") || code.equals("FARMAVIDA"));
+    }
+
+    private boolean isWeekendStay(java.time.LocalDate checkIn, java.time.LocalDate checkOut) {
+        long nights = java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
+        if (nights != 2) {
+            return false;
+        }
+        return checkIn.getDayOfWeek() == java.time.DayOfWeek.FRIDAY
+                && checkOut.getDayOfWeek() == java.time.DayOfWeek.SUNDAY;
+    }
+
