  1	package hotel.reservations;
  2	
  3	import hotel.rooms.Room;
  4	import java.math.BigDecimal;
  5	import java.math.RoundingMode;
  6	import java.time.DayOfWeek;
  7	import java.time.LocalDate;
  8	import java.time.Month;
  9	
 10	/**
 11	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
 12	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
 13	 * (half-even) at every step.
 14	 */
 15	public final class PriceCalculator {
 16	
 17	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
 18	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 19	    static final BigDecimal CORPORATE_TECNOSUL = new BigDecimal("0.12");
 20	    static final BigDecimal CORPORATE_AGROVALE = new BigDecimal("0.18");
 21	    static final BigDecimal CORPORATE_FARMAVIDA = new BigDecimal("0.25");
 22	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
 23	
 24	    public Price calculate(
 25	            Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
 26	        return switch (ratePlan) {
 27	            case STANDARD, NON_REFUNDABLE -> calculateStandard(room, checkIn, checkOut, ratePlan);
 28	            case CORPORATE -> calculateCorporate(room, checkIn, checkOut, companyCode);
 29	            case WEEKEND_PACKAGE -> calculateWeekendPackage(room, checkIn, checkOut);
 30	            case LONG_STAY -> calculateLongStay(room, checkIn, checkOut);
 31	        };
 32	    }
 33	
 34	    private Price calculateStandard(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
 35	        int nights = 0;
 36	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 37	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 38	            subtotal = subtotal.add(nightPrice(room, night));
 39	            nights++;
 40	        }
 41	        BigDecimal discount = switch (ratePlan) {
 42	            case STANDARD -> cents(BigDecimal.ZERO);
 43	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
 44	            default -> throw new AssertionError();
 45	        };
 46	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 47	    }
 48	
 49	    private Price calculateCorporate(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
 50	        int nights = 0;
 51	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 52	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 53	            subtotal = subtotal.add(nightPrice(room, night));
 54	            nights++;
 55	        }
 56	        BigDecimal discountRate = discountForCompany(companyCode);
 57	        BigDecimal discount = cents(subtotal.multiply(discountRate));
 58	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 59	    }
 60	
 61	    private Price calculateWeekendPackage(Room room, LocalDate checkIn, LocalDate checkOut) {
 62	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
 63	        BigDecimal price = packagePrice(room, nights);
 64	        return new Price(nights, price, cents(BigDecimal.ZERO), price);
 65	    }
 66	
 67	    private Price calculateLongStay(Room room, LocalDate checkIn, LocalDate checkOut) {
 68	        int nights = 0;
 69	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 70	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 71	            subtotal = subtotal.add(nightPrice(room, night));
 72	            nights++;
 73	        }
 74	        BigDecimal discount = cents(subtotal.multiply(LONG_STAY_DISCOUNT));
 75	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 76	    }
 77	
 78	    private BigDecimal discountForCompany(String code) {
 79	        if (code == null) {
 80	            throw new IllegalArgumentException("company code is required for CORPORATE plan");
 81	        }
 82	        return switch (code) {
 83	            case "TECNOSUL" -> CORPORATE_TECNOSUL;
 84	            case "AGROVALE" -> CORPORATE_AGROVALE;
 85	            case "FARMAVIDA" -> CORPORATE_FARMAVIDA;
 86	            default -> throw new IllegalArgumentException("invalid company code: " + code);
 87	        };
 88	    }
 89	
 90	    private BigDecimal packagePrice(Room room, int nights) {
 91	        return switch (room.type().name()) {
 92	            case "STANDARD" -> cents(new BigDecimal("520.00"));
 93	            case "DELUXE" -> cents(new BigDecimal("820.00"));
 94	            case "SUITE" -> cents(new BigDecimal("1200.00"));
 95	            default -> throw new AssertionError("unknown room type: " + room.type());
 96	        };
 97	    }
 98	
 99	    BigDecimal nightPrice(Room room, LocalDate night) {
100	        BigDecimal nightlyRate = room.nightlyRate();
101	        if (isHighSeason(night)) {
102	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
103	        }
104	        return cents(nightlyRate);
105	    }
106	
107	    /** High season: from December 15 to the end of February, and the whole of July. */
108	    static boolean isHighSeason(LocalDate date) {
109	        Month month = date.getMonth();
110	        return month == Month.JANUARY
111	                || month == Month.FEBRUARY
112	                || month == Month.JULY
113	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
114	    }
115	
116	    static BigDecimal cents(BigDecimal value) {
117	        return value.setScale(2, RoundingMode.HALF_EVEN);
118	    }
119	}
120	package hotel.reservations;
121	
122	import hotel.documents.ReservationReceipt;
123	import hotel.messages.EmailSender;
124	import hotel.rooms.Room;
125	import hotel.rooms.Rooms;
126	import java.math.BigDecimal;
127	
128	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
129	public final class ReservationService {
130	
131	    static final String HOTEL_NAME = "Pousada Maré Alta";
132	
133	    private final Rooms rooms;
134	    private final ReservationStore store;
135	    private final PriceCalculator priceCalculator;
136	    private final EmailSender emailSender;
137	
138	    public ReservationService(
139	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
140	        this.rooms = rooms;
141	        this.store = store;
142	        this.priceCalculator = priceCalculator;
143	        this.emailSender = emailSender;
144	    }
145	
146	    public synchronized Reservation create(NewReservation request) {
147	        if (!request.checkOut().isAfter(request.checkIn())) {
148	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
149	        }
150	        if (request.guests() < 1) {
151	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
152	        }
153	        validateRatePlan(request);
154	        Room room = rooms.find(request.roomNumber())
155	                .orElseThrow(() -> new HotelException(
156	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
157	        if (request.guests() > room.capacity()) {
158	            throw new HotelException(
159	                    ErrorCode.CAPACITY_EXCEEDED,
160	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
161	        }
162	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
163	            throw new HotelException(
164	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
165	        }
166	        Price price =
167	                priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
168	        return store.add(request, price);
169	    }
170	
171	    private void validateRatePlan(NewReservation request) {
172	        switch (request.ratePlan()) {
173	            case CORPORATE:
174	                if (!isValidCompanyCode(request.companyCode())) {
175	                    throw new HotelException(ErrorCode.INVALID_REQUEST, "invalid company code");
176	                }
177	                break;
178	            case WEEKEND_PACKAGE:
179	                if (!isWeekendStay(request.checkIn(), request.checkOut())) {
180	                    throw new HotelException(ErrorCode.INVALID_REQUEST, "weekend package must be Friday to Sunday");
181	                }
182	                break;
183	            case LONG_STAY:
184	                long nights = java.time.temporal.ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
185	                if (nights < 7) {
186	                    throw new HotelException(ErrorCode.INVALID_REQUEST, "long stay requires at least 7 nights");
187	                }
188	                break;
189	            default:
190	                break;
191	        }
192	    }
193	
194	    private boolean isValidCompanyCode(String code) {
195	        return code != null && (code.equals("TECNOSUL") || code.equals("AGROVALE") || code.equals("FARMAVIDA"));
196	    }
197	
198	    private boolean isWeekendStay(java.time.LocalDate checkIn, java.time.LocalDate checkOut) {
199	        long nights = java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
200	        if (nights != 2) {
201	            return false;
202	        }
203	        return checkIn.getDayOfWeek() == java.time.DayOfWeek.FRIDAY
204	                && checkOut.getDayOfWeek() == java.time.DayOfWeek.SUNDAY;
205	    }
206	
207	    public Reservation find(long reservationId) {
208	        return store.find(reservationId)
209	                .orElseThrow(() -> new HotelException(
210	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
211	    }
212	
213	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
214	    public synchronized Reservation confirm(long reservationId) {
215	        Reservation reservation = find(reservationId);
216	        if (reservation.status() != ReservationStatus.PENDING) {
217	            throw notAllowed(reservation, "confirm");
218	        }
219	        reservation.confirmPayment();
220	        store.update(reservation);
221	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
222	        emailSender.send(
223	                reservation.guest().email(),
224	                "Reserva confirmada - " + HOTEL_NAME,
225	                confirmationEmailBody(reservation, receipt));
226	        return reservation;
227	    }
228	
229	    /**
230	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
231	     * reservation was never paid, so nothing comes back).
232	     */
233	    public synchronized Reservation cancel(long reservationId) {
234	        Reservation reservation = find(reservationId);
235	        if (reservation.status() != ReservationStatus.PENDING
236	                && reservation.status() != ReservationStatus.CONFIRMED) {
237	            throw notAllowed(reservation, "cancel");
238	        }
239	        BigDecimal refund = switch (reservation.ratePlan()) {
240	            case STANDARD, CORPORATE, LONG_STAY -> reservation.amountPaid();
241	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
242	            case WEEKEND_PACKAGE -> PriceCalculator.cents(reservation.amountPaid().divide(
243	                    BigDecimal.TWO, 2, java.math.RoundingMode.HALF_EVEN));
244	        };
245	        reservation.cancel(refund);
246	        store.update(reservation);
247	        return reservation;
248	    }
249	
250	    public synchronized Reservation checkIn(long reservationId) {
251	        Reservation reservation = find(reservationId);
252	        if (reservation.status() != ReservationStatus.CONFIRMED) {
253	            throw notAllowed(reservation, "check in");
254	        }
255	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
256	        store.update(reservation);
257	        return reservation;
258	    }
259	
260	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
261	    public synchronized ReservationReceipt checkOut(long reservationId) {
262	        Reservation reservation = find(reservationId);
263	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
264	            throw notAllowed(reservation, "check out");
265	        }
266	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
267	        store.update(reservation);
268	        return new ReservationReceipt(reservation, roomOf(reservation));
269	    }
270	
271	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
272	    public ReservationReceipt receiptCopy(long reservationId) {
273	        Reservation reservation = find(reservationId);
274	        if (!reservation.isPaid()) {
275	            throw notAllowed(reservation, "issue a receipt for");
276	        }
277	        return new ReservationReceipt(reservation, roomOf(reservation));
278	    }
279	
280	    private Room roomOf(Reservation reservation) {
281	        return rooms.find(reservation.roomNumber()).orElseThrow();
282	    }
283	
284	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
285	        return "Olá, " + reservation.guest().name() + "!\n\n"
286	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
287	                + receipt.text() + "\n"
288	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
289	                + "Até breve!\n";
290	    }
291	
292	    private static HotelException notAllowed(Reservation reservation, String operation) {
293	        return new HotelException(
294	                ErrorCode.OPERATION_NOT_ALLOWED,
295	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
296	    }
297	}

