184	                long nights = java.time.temporal.ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
185	                if (nights < 7) {
186	                    throw new HotelException(ErrorCode.INVALID_REQUEST, "long stay requires at least 7 nights");
187	                }
188	                break;
189	            default:
190	                break;
191	        }
192	    }
193	
194	    private boolean isValidCompanyCode(String code) {
195	        return code != null && (code.equals("TECNOSUL") || code.equals("AGROVALE") || code.equals("FARMAVIDA"));
196	    }
197	
198	    private boolean isWeekendStay(java.time.LocalDate checkIn, java.time.LocalDate checkOut) {
199	        long nights = java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
200	        if (nights != 2) {
201	            return false;
202	        }
203	        return checkIn.getDayOfWeek() == java.time.DayOfWeek.FRIDAY
204	                && checkOut.getDayOfWeek() == java.time.DayOfWeek.SUNDAY;
205	    }
206	
207	    public Reservation find(long reservationId) {
208	        return store.find(reservationId)
209	                .orElseThrow(() -> new HotelException(
210	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
211	    }
212	
213	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
214	    public synchronized Reservation confirm(long reservationId) {
215	        Reservation reservation = find(reservationId);
216	        if (reservation.status() != ReservationStatus.PENDING) {
217	            throw notAllowed(reservation, "confirm");
218	        }
219	        reservation.confirmPayment();
220	        store.update(reservation);
221	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
222	        emailSender.send(
223	                reservation.guest().email(),
224	                "Reserva confirmada - " + HOTEL_NAME,
225	                confirmationEmailBody(reservation, receipt));
226	        return reservation;
227	    }
228	
229	    /**
230	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
231	     * reservation was never paid, so nothing comes back).
232	     */
233	    public synchronized Reservation cancel(long reservationId) {
234	        Reservation reservation = find(reservationId);
235	        if (reservation.status() != ReservationStatus.PENDING
236	                && reservation.status() != ReservationStatus.CONFIRMED) {
237	            throw notAllowed(reservation, "cancel");
238	        }
239	        BigDecimal refund = switch (reservation.ratePlan()) {
240	            case STANDARD, CORPORATE, LONG_STAY -> reservation.amountPaid();
241	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
242	            case WEEKEND_PACKAGE -> PriceCalculator.cents(reservation.amountPaid().divide(
243	                    BigDecimal.TWO, 2, java.math.RoundingMode.HALF_EVEN));
244	        };
245	        reservation.cancel(refund);
246	        store.update(reservation);
247	        return reservation;
248	    }
249	
250	    public synchronized Reservation checkIn(long reservationId) {
251	        Reservation reservation = find(reservationId);
252	        if (reservation.status() != ReservationStatus.CONFIRMED) {
253	            throw notAllowed(reservation, "check in");
254	        }
255	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
256	        store.update(reservation);
257	        return reservation;
258	    }
259	
260	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
261	    public synchronized ReservationReceipt checkOut(long reservationId) {
262	        Reservation reservation = find(reservationId);
263	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
264	            throw notAllowed(reservation, "check out");
265	        }
266	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
267	        store.update(reservation);
268	        return new ReservationReceipt(reservation, roomOf(reservation));
269	    }
270	
271	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
272	    public ReservationReceipt receiptCopy(long reservationId) {
273	        Reservation reservation = find(reservationId);
274	        if (!reservation.isPaid()) {
275	            throw notAllowed(reservation, "issue a receipt for");
276	        }
277	        return new ReservationReceipt(reservation, roomOf(reservation));
278	    }
279	
280	    private Room roomOf(Reservation reservation) {
281	        return rooms.find(reservation.roomNumber()).orElseThrow();
282	    }
283	
284	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
285	        return "Olá, " + reservation.guest().name() + "!\n\n"
286	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
287	                + receipt.text() + "\n"
288	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
289	                + "Até breve!\n";
290	    }
291	
292	    private static HotelException notAllowed(Reservation reservation, String operation) {
293	        return new HotelException(
294	                ErrorCode.OPERATION_NOT_ALLOWED,
295	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
296	    }
297	}

